/* roles */
ROLES.pm.scope=T("Order of work and dependencies between the four teams, sprint contents, statuses, go / no-go. Keeps Jira in line with the repositories.","Порядок робіт і залежності між чотирма командами, склад спринту, статуси, go / no-go. Стежить, щоб Jira відповідала репозиторіям.");
ROLES.pm.ctx=["docs/roadmap.md",".size, .route",T("tasks.json from four repositories","tasks.json із чотирьох репозиторіїв"),T("Jira: sprint capacity","Jira: місткість спринту"),T("review record, QA report","review record, звіт QA")];
ROLES.pm.to=[["des",T("epic, start of ux-flows","епік, старт ux-flows")],["dev",T("stories in the sprint, by team","задачі в спринті, по командах")],["qa",T("epic in the sprint","епік у спринті")],["ops",T("go / no-go and the release window","go / no-go і вікно релізу")]];
ROLES.des.scope=T("User flows, every screen in every state for web, Android and iOS, design-system components.","Шляхи користувача, екрани в усіх станах для вебу, Android та iOS, компоненти дизайн-системи.");
ROLES.dev.name=T("Developers: Backend, Web, Android, iOS","Розробники: Backend, Web, Android, iOS");
ROLES.dev.scope=T("Four teams, each with its own repository and stack. Backend leads the technical design, the data model and the API contract. Web, Android and iOS build against that contract. Every team runs tasks, implement, review and ship in its own repository.","Чотири команди, кожна зі своїм репозиторієм і стеком. Backend веде технічний дизайн, модель даних і контракт API. Web, Android та iOS будують під цей контракт. Кожна команда веде tasks, implement, review і ship у своєму репозиторії.");
ROLES.dev.tools=[T("Claude Code with the SDD plugin","Claude Code з плагіном SDD"),"git, GitLab, GitLab CI",T("SDD agents: test-author, implementer, reviewer","агенти SDD: test-author, implementer, reviewer")];
ROLES.dev.ctx=["CLAUDE.md","docs/architecture-map.md",T("shared files synced from product-specs","спільні файли, синхронізовані з product-specs"),T("the team's own code","код своєї команди")];
ROLES.dev.out=["`sad.md`, `adr/*`",T("backend: `data-model.md`, migrations, `contracts/openapi.yaml`","backend: `data-model.md`, міграції, `contracts/openapi.yaml`"),T("`tasks.json` in each repository","`tasks.json` у кожному репозиторії"),T("code and tests","код і тести"),T("review record, changelog, merge request","review record, changelog, merge request")];
ROLES.dev.to=[["des",T("contract with error codes","контракт з кодами помилок")],["pm",T("four `tasks.json` files","чотири файли `tasks.json`")],["ops",T("approved merge requests, backend first","погоджені merge request, першим backend")],["qa",T("review record, changelog","review record, changelog")]];
ROLES.qa.scope=T("Test plan derived from AC for web, Android and iOS, verification on staging, e2e, bugs traced to an AC and to the team that owns them, retest. Decides what counts as a bug: the model proposes, the tester confirms.","План тестів від AC для вебу, Android та iOS, перевірка на стенді, e2e, баги з прив'язкою до AC і до команди-власника, ретест. Вирішує, що є багом: модель пропонує, тестувальник підтверджує.");
ROLES.qa.tools=[T("Claude Code with the SDD plugin","Claude Code з плагіном SDD"),T("Playwright for the web admin","Playwright для вебадмінки"),T("Maestro for Android and iOS","Maestro для Android та iOS"),"Jira"];
ROLES.qa.ctx=["spec.md (AC)","ux-flows.md","screens.md","test-plan.md","contracts/openapi.yaml",T("staging and the test builds","стенд і тестові збірки")];
ROLES.qa.to=[["dev",T("bug → `/sdd:fix` in the owning team","баг → `/sdd:fix` у команді-власника")],["po",T("questions about AC","питання до AC")],["des",T("mismatch with the mockup","розбіжність із макетом")],["pm",T("report: passed or not","звіт: пройдено чи ні")],["ops",T("test data and accounts staging needs","дані й облікові записи для стенду")]];
ROLES.ops={name:T("Admin / DevOps / Release manager","Адмін / DevOps / реліз-менеджер"),l:T("Ops / Release","Ops / реліз"),s:"Ops",
  scope:T("Claude seats, policy and spend limits. GitLab groups, protected branches and pipelines. Staging with seeded data. The order of the release, the rollout, monitoring and rollback.","Місця Claude, політики й ліміти витрат. Групи GitLab, захищені гілки та пайплайни. Стенд із підготовленими даними. Порядок релізу, розкатка, моніторинг і відкат."),
  tools:[T("Claude admin console: seats, spend limits, managed settings","Адмін-консоль Claude: місця, ліміти витрат, керовані налаштування"),T("GitLab CI/CD, with an optional Claude Code job","GitLab CI/CD, за бажанням із job Claude Code"),T("Claude Code in the terminal","Claude Code у терміналі"),T("your error and crash monitoring","ваш моніторинг помилок і крешів")],
  ctx:[".gitlab-ci.yml","test-plan.md",T("merge requests and pipelines","merge request і пайплайни"),"changelog",T("Jira: epic state","Jira: стан епіка")],
  cmds:[T("no SDD stages: own prompts","без стадій SDD: власні промпти"),"claude -p … (.gitlab-ci.yml)"],
  out:[T("staging with the backend, the web admin and two test builds","стенд із backend, вебадмінкою та двома тестовими збірками"),T("production release in the right order","реліз на продакшен у правильному порядку"),T("Confluence: release notes","Confluence: нотатки до релізу"),T("Jira: epic closed","Jira: епік закрито")],
  to:[["qa",T("staging URL, build numbers, test accounts","адреса стенду, номери збірок, тестові облікові записи")],["dev",T("a production problem → `/sdd:fix`","проблема на продакшені → `/sdd:fix`")],["po",T("what production showed","що показав продакшен")]]};

