STEPS.push(
 {id:"staging",role:"ops",label:T("staging","стенд"),team:true,title:T("Deploy to staging and hand the builds to QA","Викладка на стенд і передача збірок QA"),jira:"QA",
  cmds:[],
  does:[T("The pipeline deploys the backend to staging first and applies the migrations there.","Пайплайн першим викладає на стенд backend і застосовує там міграції."),
        T("The clients switch from the mock to staging. CI then builds what QA installs: the web admin on staging, an Android internal build and an iOS TestFlight build.","Клієнти перемикаються з мока на стенд. Далі CI збирає те, що встановить QA: вебадмінку на стенді, внутрішню збірку Android і збірку iOS у TestFlight."),
        T("Staging runs on seeded data and the test accounts from the test plan. No production customer data.","Стенд працює на підготовлених даних і тестових облікових записах із плану тестів. Жодних даних реальних клієнтів."),
        T("A smoke check on all three clients runs before QA is called.","Перед тим як кликати QA, на всіх трьох клієнтах проходить smoke-перевірка.")],
  reads:[T("approved merge requests","погоджені merge request"),"test-plan.md",".gitlab-ci.yml"],
  mcp:[[GL,T("reads the deploy jobs and the build numbers","читає deploy-job і номери збірок")],[ATL,T("moves the epic to QA with the build links","переводить епік у QA з посиланнями на збірки")]],
  writes:[[T("staging deploy","викладка на стенд"),T("backend first with its migrations, then the web admin","спершу backend з міграціями, потім вебадмінка")],[T("Android and iOS test builds","тестові збірки Android та iOS"),T("internal track and TestFlight, both pointing at staging","internal track і TestFlight, обидві дивляться на стенд")],[T("Jira: epic SHOP-412","Jira: епік SHOP-412"),T("status QA","статус QA")]],
  handoff:[["qa",T("Staging URL, Android and iOS build numbers, test accounts.","Адреса стенду, номери збірок Android та iOS, тестові облікові записи.")]],
  example:T("staging  backend   v2.31.0-rc1        migrations ok\n         web       admin.staging…     build 884\n         android   internal track     2.31.0 (4127)\n         ios       TestFlight         2.31.0 (512)\nsmoke    sign in → order 1042 → create task\n         passed on web, android, ios",
            "стенд    backend   v2.31.0-rc1        міграції ok\n         web       admin.staging…     збірка 884\n         android   internal track     2.31.0 (4127)\n         ios       TestFlight         2.31.0 (512)\nsmoke    вхід → замовлення 1042 → створити завдання\n         пройдено на web, android, ios")},
 {id:"accept",role:"po",label:T("accept","приймання"),short:T("accept","прийм."),team:true,title:T("Acceptance and go / no-go","Приймання і go / no-go"),jira:"Acceptance",
  cmds:[],
  does:[T("The analyst walks the AC on staging, in the web admin and in one mobile app, and confirms this is the feature they described.","Аналітик проходить AC на стенді, у вебадмінці та в одному мобільному застосунку, і підтверджує, що це та фіча, яку він описав."),
        T("The PM checks that stories are closed, no blocker is open and all four merge requests are approved, then gives the go or no-go and the release window.","PM перевіряє, що задачі закриті, блокерів немає й усі чотири merge request погоджено, а потім дає go або no-go і вікно релізу."),
        T("Claude drafts the release notes from the four changelogs.","Claude готує чернетку нотаток до релізу з чотирьох changelog.")],
  reads:[T("Confluence: QA report","Confluence: звіт QA"),"changelog ×4","spec.md",T("Jira: epic state","Jira: стан епіка")],
  mcp:[[ATL,T("moves the epic to Acceptance, saves the draft notes","переводить епік в Acceptance, зберігає чернетку нотаток")],[GL,T("reads the four changelogs","читає чотири changelog")]],
  writes:[["Jira: SHOP-412",T("accepted, go for release","прийнято, go на реліз")],[T("Confluence: release notes","Confluence: нотатки до релізу"),T("draft","чернетка")]],
  handoff:[["ops",T("Go, the release window and the release notes.","Go, вікно релізу й нотатки до релізу.")]]},
 {id:"release",role:"ops",label:T("release","реліз"),team:true,title:T("Release in order, then watch production","Реліз у правильному порядку і нагляд за продакшеном"),jira:"Done",
  cmds:[],
  does:[T("Order: backend to production, then the web admin, then the mobile apps. The API stays backward compatible, because older app versions keep calling it.","Порядок: backend на продакшен, далі вебадмінка, далі мобільні застосунки. API лишається зворотно сумісним, бо старі версії застосунків і далі його викликають."),
        T("A person starts every production deploy. Mobile goes out as a staged rollout, and a feature flag turns the feature on for staff.","Кожну викладку на продакшен запускає людина. Мобільні застосунки виходять поетапно, а фічу для працівників вмикає feature flag."),
        T("Watches error and crash rates for the first day. If they jump: flag off or rollback, then a hotfix through `/sdd:fix`.","Першу добу стежить за помилками та крешами. Якщо вони стрибнули: вимкнути flag або відкотити, далі хотфікс через `/sdd:fix`."),
        T("Closes the epic and passes what production showed to the analyst, for the next spec.","Закриває епік і передає аналітику, що показав продакшен, для наступного spec.")],
  reads:[T("go and the release window","go і вікно релізу"),"changelog ×4",T("error and crash dashboards","дашборди помилок і крешів")],
  mcp:[[GL,T("reads pipelines and tags","читає пайплайни й теги")],[ATL,T("publishes the notes, closes the epic","публікує нотатки, закриває епік")]],
  writes:[[T("production deploys","викладки на продакшен"),T("backend, then the web admin","backend, далі вебадмінка")],[T("store rollouts","розкатка в магазинах"),T("Android staged rollout, iOS phased release","поетапна розкатка Android, phased release iOS")],["Jira: SHOP-412","Done"],[T("Confluence: release notes","Confluence: нотатки до релізу"),T("published","опубліковано")],["docs/roadmap.md",T("marked shipped by the PM","статус shipped ставить PM")]],
  handoff:[["po",T("What production showed in the first days: errors, crashes, support tickets.","Що показав продакшен у перші дні: помилки, креші, звернення в підтримку.")]],
  example:T("1  backend   v2.31.0   production   migrations ok\n2  web       admin     production\n3  android   2.31.0    Play: staged rollout 10% → 50% → 100%\n4  ios       2.31.0    App Store: phased release\n\nflag   tasks_issues on for staff after step 2\nwatch  24 h: API 5xx, crash-free sessions, notification queue",
            "1  backend   v2.31.0   продакшен   міграції ok\n2  web       admin     продакшен\n3  android   2.31.0    Play: поетапна розкатка 10% → 50% → 100%\n4  ios       2.31.0    App Store: phased release\n\nflag     tasks_issues увімкнено для працівників після кроку 2\nнагляд   24 год: API 5xx, сесії без крешів, черга сповіщень")}
);
