 reads:["docs/roadmap.md",T("Confluence: “Research: order problems handed over in chat”","Confluence: «Дослідження: проблеми із замовленнями в чатах»"),T("Jira: tickets labelled order-followup","Jira: звернення з міткою order-followup")],
