ov("tasks",{title:T("Tasks in each team's repository","Задачі в репозиторії кожної команди"),
 cmds:["/sdd:design "+SLUG,"/sdd:tasks "+SLUG],
 does:[T("Each team works in its own repository. The shared files (spec, flows, screens, contract) arrive there as a sync merge request from `product-specs`.","Кожна команда працює у своєму репозиторії. Спільні файли (spec, шляхи, екрани, контракт) потрапляють туди через sync merge request із `product-specs`."),
       T("Web, Android and iOS first run `/sdd:design` for a short client-side design, then `/sdd:tasks`. Backend already has its design and runs only `/sdd:tasks`.","Web, Android та iOS спершу запускають `/sdd:design` для короткого клієнтського дизайну, потім `/sdd:tasks`. Backend уже має дизайн і запускає лише `/sdd:tasks`."),
       T("Each `tasks.json` holds tasks of a day or less with a dependency graph. A client task that needs the real API is marked as waiting for the backend.","Кожен `tasks.json` містить задачі до одного дня з графом залежностей. Клієнтська задача, якій потрібен справжній API, позначена як така, що чекає на backend."),
       T("Each ui task names the SCR ids and states it must cover.","Кожна ui-задача називає SCR і стани, які має покрити.")],
 reads:["spec.md","sad.md","contracts/openapi.yaml","screens.md","docs/architecture-map.md"],
 writes:[["tasks/*",""],["tasks.json",T("one per repository","по одному на репозиторій")],["sad.md",T("short client-side design in web, Android and iOS","короткий клієнтський дизайн у web, Android та iOS")]],
 handoff:[["pm",T("Four `tasks.json` files to carry over into Jira.","Чотири файли `tasks.json` для перенесення в Jira.")]],
 example:T("backend/tasks.json\n  T-01  staff_tasks migration\n  T-02  POST and PATCH tasks           ← T-01\n  T-03  notify on assignment           ← T-02\n\nweb-admin/tasks.json   (android-app, ios-app: same shape)\n  T-01  ui: SCR-01, SCR-02 on the mock\n  T-02  ui: SCR-03 My tasks on the mock\n  T-03  switch to the staging API      ← backend T-02",
           "backend/tasks.json\n  T-01  міграція staff_tasks\n  T-02  POST і PATCH завдань            ← T-01\n  T-03  сповіщення про призначення      ← T-02\n\nweb-admin/tasks.json   (android-app, ios-app: так само)\n  T-01  ui: SCR-01, SCR-02 на моку\n  T-02  ui: SCR-03 Мої завдання на моку\n  T-03  перемикання на API стенду       ← backend T-02")});
ov("sprint",{
 does:[T("Claude reads the four `tasks.json` files through GitLab MCP and creates stories under the epic through Atlassian MCP, each labelled with its team.","Claude читає чотири файли `tasks.json` через GitLab MCP і через Atlassian MCP створює задачі під епіком, кожну з міткою команди."),
       T("Cross-team links are explicit: every client's integration story is blocked by the backend API story. This is the wait the plan has to show.","Зв'язки між командами явні: інтеграційну задачу кожного клієнта блокує задача backend з API. Саме це очікування план має показувати."),
       T("The PM orders the sprint so backend starts first and the clients work on the mock meanwhile. Sync goes one way, from the repositories to Jira.","PM складає спринт так, щоб backend стартував першим, а клієнти тим часом працювали на моку. Синхронізація йде в один бік, з репозиторіїв у Jira.")],
 reads:[T("tasks.json in four repositories","tasks.json у чотирьох репозиторіях"),".size",T("Jira: sprint capacity","Jira: місткість спринту")],
 mcp:[[GL,T("reads tasks.json from the four repositories","читає tasks.json із чотирьох репозиторіїв")],[ATL,T("creates stories and blocks links, adds them to the sprint","створює задачі, зв'язки blocks, додає у спринт")]],
 writes:[["Jira: SHOP-413…424",T("one per task, labelled by team","по одній на задачу, з міткою команди")],[T("Confluence: sprint plan","Confluence: план спринту"),""]],
 handoff:[["dev",T("Stories in the sprint by team. Backend first; the client integration stories wait for it.","Задачі в спринті по командах. Спершу backend; інтеграційні задачі клієнтів чекають на нього.")],["qa",T("The epic is in the sprint: time to prepare the test plan.","Епік у спринті: час готувати план тестів.")]]});
ov("plantests",{
 does:[T("Every AC maps to at least one test and to the platforms it must pass on: web, Android, iOS.","Кожному AC відповідає щонайменше один тест і платформи, на яких він має пройти: веб, Android, iOS."),
       T("E2E paths come from `ux-flows.md`, component states from `screens.md`. Web runs in Playwright, Android and iOS in Maestro.","E2E-шляхи беруться з `ux-flows.md`, стани компонентів зі `screens.md`. Веб проходить у Playwright, Android та iOS у Maestro."),
       T("The tester adds what the model does not know: past bugs, risky areas, and the test data and accounts staging needs.","Тестувальник додає те, чого модель не знає: минулі баги, ризикові місця, а також дані й облікові записи, потрібні на стенді.")],
 handoff:[["dev",T("`test-plan.md`. `implement` writes tests to this plan.","`test-plan.md`. `implement` пише тести за цим планом.")],["ops",T("The test data and accounts staging needs.","Дані й облікові записи, потрібні на стенді.")]],
 example:T("AC-3    integration  backend            reassigning twice → one notification each\nAC-4    integration  backend            no access to the order → 403, not listed\nAC-1    e2e          web, android, ios  order page → create task → shows in the block\nSCR-02  component    web, android, ios  all five states",
           "AC-3    integration  backend            два перепризначення → по одному сповіщенню\nAC-4    integration  backend            немає доступу до замовлення → 403\nAC-1    e2e          web, android, ios  замовлення → створити завдання → видно в блоці\nSCR-02  component    web, android, ios  усі п'ять станів")});
ov("implement",{title:T("Implementation through TDD: real API, clients on a mock","Реалізація через TDD: справжній API, клієнти на моку"),
 does:[BY.implement.does[0],
       T("Backend builds the real API. Web, Android and iOS build their screens against a mock generated from the contract, so nobody sits idle.","Backend будує справжній API. Web, Android та iOS збирають екрани на моку, згенерованому з контракту, тож ніхто не простоює."),
       T("A client is done only after it switches from the mock to the backend on staging. That last task is the one that waits.","Клієнт готовий лише після перемикання з мока на backend на стенді. Саме ця остання задача чекає."),
       T("A gate on every task: unit, integration, lint. Commits carry `SDD-Task` and `SDD-AC` trailers, so code traces back to a criterion.","Гейт на кожній задачі: unit, integration, lint. Коміти мають трейлери `SDD-Task` і `SDD-AC`, тож код простежується до критерію.")],
 reads:["tasks.json","test-plan.md","screens.md","contracts/openapi.yaml","docs/architecture-map.md","CLAUDE.md"]});
ov("review",{
 does:[T("In each repository a reviewer agent in a clean context reads the whole diff and checks it against the spec, the AC and code quality.","У кожному репозиторії агент-рев'юер у чистому контексті читає весь diff і звіряє його зі spec, AC та якістю коду."),
       T("Traces every story and AC through the artifacts down to the code, and compares the built screens with `screens.md`.","Простежує кожну історію й AC через артефакти аж до коду та звіряє зібрані екрани зі `screens.md`."),
       T("The verdict is PASS or CHANGES REQUESTED. The second sends the work back to `implement`.","Вердикт PASS або CHANGES REQUESTED. Другий повертає роботу в `implement`."),
       T("The GitLab pipeline runs the tests and the security scan. AI review approves nothing: a human code owner approves the merge request.","Пайплайн GitLab запускає тести й перевірку безпеки. Рев'ю від ШІ нічого не погоджує: merge request погоджує людина, власник коду.")],
 mcp:[[GL,T("reads the diff and the pipeline result","читає diff і результат пайплайна")]]});
ov("ship",{title:T("Run it, changelog, merge request","Запуск, changelog, merge request"),jira:"Ready for Staging",
 does:[T("Each team runs its part for real and verifies it against the AC. Green tests alone are not enough for that.","Кожна команда запускає свою частину по-справжньому й перевіряє її проти AC. Зелених тестів для цього мало."),
       T("Writes the changelog and opens the merge request in the team's repository. Never merges on its own.","Пише changelog і відкриває merge request у репозиторії команди. Сам ніколи не мержить."),
       T("Four merge requests in total, each approved by a code owner. Backend goes to staging first.","Разом чотири merge request, кожен погоджує власник коду. На стенд першим іде backend.")],
 mcp:[[GL,T("opens the merge request","відкриває merge request")],[ATL,T("moves the stories to Ready for Staging","переводить задачі в Ready for Staging")]],
 writes:[["MR",T("with changelog and review record, one per repository","з changelog і review record, по одному на репозиторій")]],
 handoff:[["ops",T("Approved merge requests with green pipelines. Backend first.","Погоджені merge request із зеленими пайплайнами. Першим backend.")]]});
ov("verify",{title:T("AI-assisted verification on staging: web, Android, iOS","Перевірка на стенді з ШІ: веб, Android, iOS"),
 does:[T("Web: Claude Code drives the browser through Playwright MCP. Android and iOS: it drives an emulator or a simulator through Maestro MCP. It walks every path in `ux-flows.md` on each platform.","Веб: Claude Code керує браузером через Playwright MCP. Android та iOS: керує емулятором або симулятором через Maestro MCP. Проходить кожен шлях з `ux-flows.md` на кожній платформі."),
       T("Compares screen states with `screens.md` and the Figma mockups, and API responses with the contract.","Звіряє стани екранів зі `screens.md` і макетами у Figma, а відповіді API з контрактом."),
       BY.verify.does[2],
       T("Each finding becomes a Jira bug traced to an AC, with the platform and the team that owns it. Stable scenarios stay as Playwright specs and Maestro flows in the client repositories.","Кожна знахідка стає багом у Jira з прив'язкою до AC, платформою й командою-власником. Стабільні сценарії лишаються як специ Playwright і flows Maestro в клієнтських репозиторіях.")],
 reads:["spec.md (AC)","ux-flows.md","screens.md","test-plan.md","contracts/openapi.yaml",T("staging and the test builds","стенд і тестові збірки")],
 mcp:[["Playwright",T("drives the browser on staging","керує браузером на стенді")],["Maestro",T("drives the emulator and the simulator","керує емулятором і симулятором")],[ATL,T("creates bugs, updates statuses","створює баги, оновлює статуси")],["Figma",T("compares a screen with its mockup","порівнює екран з макетом")]],
 writes:[[T("Jira: bugs under SHOP-412","Jira: баги під SHOP-412"),T("AC, platform, owning team, steps, expected, actual, screenshot","AC, платформа, команда-власник, кроки, очікуване, фактичне, скриншот")],[T("e2e tests","e2e-тести"),T("Playwright specs and Maestro flows in the client repositories","специ Playwright і flows Maestro в клієнтських репозиторіях")],[T("Confluence: test run report","Confluence: звіт про проходження"),T("a result for every AC on every platform","результат на кожен AC на кожній платформі")]]});
BY.fix.does[0]=T("The team that owns the bug runs it in its own repository. It reproduces the bug and names the cause: regression, ambiguous AC or uncovered gap.","Команда-власник бага запускає її у своєму репозиторії. Відтворює баг і називає причину: регресія, нечіткий AC або непокрита прогалина.");
BY.fix.reads=[T("Jira: bug","Jira: баг"),"spec.md",T("the owning team's code","код команди-власника")];

/* which team does what at the engineering steps: backend, web, android, ios */
var TEAMS=["Backend","Web","Android","iOS"];
var TSTATE={lead:T("leads","веде"),work:T("works","працює"),rev:T("reviews","рев'ює"),appr:T("approves","погоджує"),wait:T("waits","чекає"),mock:T("on the mock","на моку"),real:T("real API","справжній API"),integ:T("to staging","на стенд"),first:T("first","перший"),after:T("after backend","після backend"),mr:T("opens MR","відкриває MR")};
var STEAM={design:["lead","rev","rev","rev"],datamodel:["work","wait","wait","wait"],api:["lead","appr","appr","appr"],tasks:["work","work","work","work"],
 implement:["real","mock","mock","mock"],review:["work","work","work","work"],ship:["mr","mr","mr","mr"],staging:["first","integ","integ","integ"],release:["first","after","after","after"]};
U.teamsK=T("Teams","Команди");

/* who signs off each step: a person, never the model */
U.gateK=T("Sign-off","Погоджує");
var GATE={
 clarify:[T("PO / analyst","PO / аналітик"),T("the spec is ready: every open question closed or deferred","spec готовий: кожне відкрите питання закрито або відкладено")],
 epic:["PM",T("size, route and the team leads","розмір, маршрут і ліди команд")],
 uxflows:[T("PO / analyst","PO / аналітик"),T("the flows match the user stories","шляхи відповідають історіям користувачів")],
 design:[T("Web, Android, iOS leads","ліди Web, Android, iOS"),T("architecture review of the backend design","архітектурне рев'ю дизайну backend")],
 datamodel:[T("Backend lead","лід backend"),T("the schema and the rollback migration","схема й міграція відкату")],
 api:[T("Web, Android, iOS leads","ліди Web, Android, iOS"),T("the contract merge request in product-specs","merge request з контрактом у product-specs")],
 screens:[T("PO and client leads","PO і ліди клієнтів"),T("every state can be built on each platform","кожен стан можна зібрати на кожній платформі")],
 tasks:[T("each team lead","лід кожної команди"),T("the task split in the team's repository","поділ на задачі в репозиторії команди")],
 sprint:["PM",T("sprint contents and the order between teams","склад спринту й порядок між командами")],
 plantests:[T("QA lead","лід QA"),T("every AC is covered on every platform","кожен AC покрито на кожній платформі")],
 implement:[T("automatic gate","автоматичний гейт"),T("tests and lint on every task; no human sign-off here","тести й lint на кожній задачі; людина тут не погоджує")],
 review:[T("code owner, a person","власник коду, людина"),T("approves each merge request in GitLab","погоджує кожен merge request у GitLab")],
 ship:[T("team lead","лід команди"),T("the part was run for real against its AC","частину запущено по-справжньому проти її AC")],
 staging:["DevOps",T("the smoke check passed on all three clients","smoke-перевірка пройшла на всіх трьох клієнтах")],
 verify:["QA",T("all AC passed on all platforms","усі AC пройдено на всіх платформах")],
 fix:["QA",T("the retest passed","ретест пройдено")],
 accept:[T("PO, then PM","PO, потім PM"),T("acceptance, then go / no-go","приймання, потім go / no-go")],
 release:[T("release manager","реліз-менеджер"),T("every production deploy and every rollout stage","кожна викладка на продакшен і кожен етап розкатки")]
};

/* return paths */
LOOPS.regress.steps[0][1]=T("Files a Jira bug: AC-4, all platforms, owner backend, steps, expected, actual, a screen recording from staging.","Заводить баг у Jira: AC-4, усі платформи, власник backend, кроки, очікуване, фактичне, запис екрана зі стенду.");
LOOPS.regress.steps[1][1]=T("Backend runs `/sdd:fix tasks-issues` in its repository with a link to the bug. Claude reproduces it, writes a failing test and applies the minimal fix.","Backend запускає `/sdd:fix tasks-issues` у своєму репозиторії з посиланням на баг. Claude відтворює, пише тест, що падає, робить мінімальне виправлення.");
LOOPS.regress.steps[3][1]=T("Repeats the scenario on web, Android and iOS, plus the neighbouring AC. The scenario stays in the e2e suite.","Повторює сценарій на вебі, Android та iOS і суміжні AC. Сценарій лишається в e2e-наборі.");
LOOPS.contract={btn:T("A client finds a gap in the contract","Клієнт знайшов прогалину в контракті"),nodes:["implement","api"],title:T("A client team finds a gap in the contract","Клієнтська команда знайшла прогалину в контракті"),
 trigger:T("iOS needs the order number in the “My tasks” list, but the list response carries only the order id. Without it the app would make one extra request per row.","iOS потребує номер замовлення у списку «Мої завдання», а у відповіді списку є лише id замовлення. Без нього застосунок робив би додатковий запит на кожен рядок."),
 steps:[["dev",T("iOS does not work around it. It raises the gap on the contract in `product-specs` and tags the backend lead.","iOS не обходить це власними силами. Фіксує прогалину на контракті в `product-specs` і позначає ліда backend.")],
        ["dev",T("Backend updates `contracts/openapi.yaml` through `/sdd:api`, keeps the change backward compatible and opens the merge request. The Web and Android leads approve it too.","Backend оновлює `contracts/openapi.yaml` через `/sdd:api`, зберігає зворотну сумісність і відкриває merge request. Його погоджують також ліди Web та Android.")],
        ["ops",T("The sync job delivers the new contract to every client repository as a merge request. The mocks are regenerated from it.","Sync-job доставляє новий контракт у кожен клієнтський репозиторій як merge request. Моки генеруються з нього заново.")],
        ["qa",T("Adds the new field to the API tests in `test-plan.md`.","Додає нове поле до API-тестів у `test-plan.md`.")]],
 updates:T("`contracts/openapi.yaml`, the mocks, backend code, `test-plan.md`","`contracts/openapi.yaml`, моки, код backend, `test-plan.md`")};
LOOPS.prod={btn:T("A problem in production","Проблема на продакшені"),nodes:["release","fix"],title:T("Production problem after the release","Проблема на продакшені після релізу"),
 trigger:T("The Android rollout reaches 10% and the crash-free rate drops: the app crashes in “My tasks” when the product linked to a task has been archived.","Розкатка Android доходить до 10%, і частка сесій без крешів падає: застосунок падає в «Мої завдання», коли товар, прив'язаний до завдання, заархівовано."),
 steps:[["ops",T("Halts the staged rollout and turns the feature flag off for Android. Files a Jira bug with the crash report.","Зупиняє поетапну розкатку й вимикає feature flag для Android. Заводить баг у Jira зі звітом про креш.")],
        ["dev",T("Android runs `/sdd:fix tasks-issues` with the crash report: a failing test, the minimal fix, a record under `_fixes/`.","Android запускає `/sdd:fix tasks-issues` зі звітом про креш: тест, що падає, мінімальне виправлення, запис у `_fixes/`.")],
        ["qa",T("Retests on staging and adds the scenario to the Maestro flows.","Робить ретест на стенді й додає сценарій до flows Maestro.")],
        ["ops",T("Ships the hotfix build and resumes the rollout.","Випускає збірку з хотфіксом і відновлює розкатку.")],
        ["po",T("If a criterion was missing, adds it to `spec.md`.","Якщо бракувало критерію, додає його в `spec.md`.")]],
 updates:T("code, tests, `_fixes/`, and `spec.md` when needed","код, тести, `_fixes/`, за потреби `spec.md`")};

/* MCP servers */
MCP=[
 {key:"atl",name:"Atlassian Rovo MCP",what:T("Jira and Confluence: search, read, create and update issues and pages.","Jira і Confluence: пошук, читання, створення й оновлення задач і сторінок."),cmd:"claude mcp add --transport http atlassian https://mcp.atlassian.com/v1/mcp/authv2",cells:{po:"rw",pm:"rw",des:"r",dev:"rw",qa:"rw",ops:"rw"}},
 {key:"fig",name:"Figma MCP",what:T("Mockup context: frames, components, tokens, node references. Writing to the canvas depends on the server version and your plan.","Контекст макетів: фрейми, компоненти, токени, посилання на вузли. Запис на полотно залежить від версії сервера й тарифу."),cmd:"claude mcp add --transport http figma https://mcp.figma.com/mcp",cells:{po:"-",pm:"-",des:"rw",dev:"r",qa:"r",ops:"-"}},
 {key:"gl",name:"GitLab MCP",what:T("Merge requests, diffs, pipelines and files in other repositories, from inside Claude Code. Beta on GitLab's side; replace gitlab.com with your own instance if you self-host. The glab CLI covers the same ground.","Merge request, diff, пайплайни й файли в інших репозиторіях прямо з Claude Code. У GitLab це бета; якщо GitLab у вас свій, замініть gitlab.com на адресу свого сервера. Те саме вміє glab CLI."),cmd:"claude mcp add -s user --transport http GitLab https://gitlab.com/api/v4/mcp",cells:{po:"-",pm:"r",des:"-",dev:"rw",qa:"rw",ops:"rw"}},
 {key:"pw",name:"Playwright MCP",what:T("Browser control for the web admin: walking paths on staging, screenshots, e2e.","Керування браузером для вебадмінки: проходження шляхів на стенді, скриншоти, e2e."),cmd:"claude mcp add playwright -- npx @playwright/mcp@latest",cells:{po:"-",pm:"-",des:"-",dev:"run",qa:"run",ops:"-"}},
 {key:"mae",name:"Maestro MCP",what:T("Mobile UI control: inspects the screen of an Android emulator or an iOS simulator, runs a flow, takes screenshots. Needs the Maestro CLI installed.","Керування мобільним інтерфейсом: читає екран емулятора Android чи симулятора iOS, запускає flow, робить скриншоти. Потрібен встановлений Maestro CLI."),cmd:"claude mcp add maestro -- maestro mcp",cells:{po:"-",pm:"-",des:"-",dev:"run",qa:"run",ops:"-"}}
];

